//! Generators: GSettings schema XML, typed Rust accessors and docs/settings.md, all from
//! [`crate::registry`]. `cargo xtask gen` writes them; tests compare them with the files in the
//! repository, so a stale artefact fails `cargo test` (and CI).

use std::fmt::Write as _;

use crate::model::*;
use crate::registry::*;
use crate::{EXTENSION_SCHEMAS, all_schemas};

/// Paths of the generated files, relative to the repository root.
pub const SCHEMA_FILE: &str = "data/io.github.OlehDzhumyk.Desk.gschema.xml";
pub const ACCESSORS_FILE: &str = "crates/desk-settings/src/accessors.rs";
pub const DOCS_FILE: &str = "docs/settings.md";

/// All generated artefacts: `(path relative to the repository root, content)`.
pub fn all() -> Vec<(String, String)> {
    let mut v = vec![
        (SCHEMA_FILE.to_string(), gschema_xml()),
        (ACCESSORS_FILE.to_string(), accessors_rs()),
        (DOCS_FILE.to_string(), settings_md()),
    ];
    v.extend(
        EXTENSION_SCHEMAS
            .iter()
            .map(|e| (e.file(), extension_gschema_xml(e))),
    );
    v
}

fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

// ------------------------------------------------------------------ GSettings XML

fn write_schema(o: &mut String, s: &Schema) {
    let _ = writeln!(o, "  <schema id=\"{}\" path=\"{}\">", s.id, s.path);
    for k in s.keys {
        let _ = writeln!(
            o,
            "    <key name=\"{}\" type=\"{}\">",
            k.name,
            k.kind.gvariant_type()
        );
        match &k.kind {
            Kind::UInt { min, max, .. } => {
                let _ = writeln!(o, "      <range min=\"{min}\" max=\"{max}\"/>");
            }
            Kind::Int { min, max, .. } => {
                let _ = writeln!(o, "      <range min=\"{min}\" max=\"{max}\"/>");
            }
            Kind::Double { min, max, .. } => {
                let _ = writeln!(o, "      <range min=\"{min:?}\" max=\"{max:?}\"/>");
            }
            Kind::Choice { choices, .. } => {
                o.push_str("      <choices>\n");
                for c in *choices {
                    let _ = writeln!(o, "        <choice value=\"{}\"/>", xml_escape(c.value));
                }
                o.push_str("      </choices>\n");
            }
            _ => {}
        }
        let _ = writeln!(
            o,
            "      <default>{}</default>",
            xml_escape(&k.kind.default_text())
        );
        let _ = writeln!(
            o,
            "      <summary>{}</summary>",
            xml_escape(k.schema_summary())
        );
        let d = k.schema_description();
        if !d.is_empty() {
            let _ = writeln!(o, "      <description>{}</description>", xml_escape(d));
        }
        o.push_str("    </key>\n");
    }
    for (name, id) in s.children {
        let _ = writeln!(o, "    <child name=\"{name}\" schema=\"{id}\"/>");
    }
    o.push_str("  </schema>\n");
}

/// The schema file of an extension (`extensions/<uuid>/schemas/`). No gettext domain: GNOME Shell
/// does not translate extension schemas, the window translates the labels from the registry.
pub fn extension_gschema_xml(e: &ExtensionSchema) -> String {
    let mut o = String::new();
    o.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    o.push_str("<!-- SPDX-License-Identifier: GPL-3.0-or-later -->\n");
    let _ = writeln!(
        o,
        "<!-- GENERATED by `cargo xtask gen` from crates/desk-settings/src/lockscreen.rs. Do not edit.\n     \
         Settings schema of the extension {}; data/install.sh compiles it next to the extension. -->",
        e.uuid
    );
    o.push_str("<schemalist>\n");
    write_schema(&mut o, e.schema);
    o.push_str("</schemalist>\n");
    o
}

pub fn gschema_xml() -> String {
    let mut o = String::new();
    o.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    o.push_str("<!-- SPDX-License-Identifier: GPL-3.0-or-later -->\n");
    o.push_str(
        "<!-- GENERATED by `cargo xtask gen` from crates/desk-settings/src/registry.rs. Do not edit.\n     \
         Settings of deskd, the shell bridge desk-bridge@desktop-themes-rs and the window: one place\n     \
         for all front ends. Installed into ~/.local/share/glib-2.0/schemas by data/install.sh. -->\n",
    );
    let _ = writeln!(o, "<schemalist gettext-domain=\"{GETTEXT_DOMAIN}\">");
    for (i, s) in SCHEMAS.iter().enumerate() {
        if i > 0 {
            o.push('\n');
        }
        write_schema(&mut o, s);
    }
    o.push_str("</schemalist>\n");
    o
}

// ------------------------------------------------------------------ typed accessors

fn snake(name: &str) -> String {
    name.replace('-', "_")
}

fn camel(s: &str) -> String {
    s.split(['-', '_'])
        .filter(|p| !p.is_empty())
        .map(|p| {
            let mut c = p.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

pub fn accessors_rs() -> String {
    let mut o = String::new();
    o.push_str(
        "// SPDX-License-Identifier: GPL-3.0-or-later\n\
         // @generated by `cargo xtask gen` from crates/desk-settings/src/registry.rs. Do not edit.\n\
         //! Typed GSettings accessors, one struct per schema (feature `gio`).\n\n\
         use gio::prelude::*;\n\n",
    );
    for s in SCHEMAS {
        // enums of choice keys
        for k in s.keys {
            if let Kind::Choice { choices, default } = &k.kind {
                let en = camel(k.name);
                let _ = writeln!(o, "/// Values of `{}` `{}`.", s.id, k.name);
                o.push_str("#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]\n");
                let _ = writeln!(o, "pub enum {en} {{");
                for c in *choices {
                    if c.value == *default {
                        o.push_str("    #[default]\n");
                    }
                    let _ = writeln!(o, "    {},", camel(c.value));
                }
                o.push_str("}\n\n");
                let _ = writeln!(o, "impl {en} {{");
                let _ = writeln!(o, "    pub const ALL: [{en}; {}] = [", choices.len());
                for c in *choices {
                    let _ = writeln!(o, "        {en}::{},", camel(c.value));
                }
                o.push_str("    ];\n\n");
                o.push_str("    pub fn as_str(self) -> &'static str {\n        match self {\n");
                for c in *choices {
                    let _ = writeln!(o, "            {en}::{} => {:?},", camel(c.value), c.value);
                }
                o.push_str("        }\n    }\n\n");
                o.push_str(
                    "    /// Unknown values (e.g. from a newer schema) fall back to the default.\n",
                );
                o.push_str("    pub fn parse(s: &str) -> Self {\n        match s {\n");
                for c in *choices {
                    let _ = writeln!(o, "            {:?} => {en}::{},", c.value, camel(c.value));
                }
                o.push_str("            _ => Self::default(),\n        }\n    }\n}\n\n");
            }
        }
        let t = s.rust_name;
        let _ = writeln!(o, "/// `{}` at `{}`.", s.id, s.path);
        o.push_str("#[derive(Clone, Debug)]\n");
        let _ = writeln!(o, "pub struct {t}(pub gio::Settings);\n");
        let _ = writeln!(o, "impl {t} {{");
        let _ = writeln!(o, "    pub const ID: &'static str = {:?};", s.id);
        for k in s.keys {
            let _ = writeln!(
                o,
                "    pub const {}: &'static str = {:?};",
                snake(k.name).to_uppercase(),
                k.name
            );
        }
        o.push_str(
            "\n    /// `None` when the schema is not installed (`gio::Settings::new` would abort).\n",
        );
        o.push_str("    pub fn new() -> Option<Self> {\n");
        o.push_str("        crate::schema_installed(Self::ID).then(|| Self(gio::Settings::new(Self::ID)))\n    }\n");
        for k in s.keys {
            let m = snake(k.name);
            let key = snake(k.name).to_uppercase();
            let (ty, get, set) = match &k.kind {
                Kind::Bool { .. } => (
                    "bool".to_string(),
                    format!("self.0.boolean(Self::{key})"),
                    format!("self.0.set_boolean(Self::{key}, v)"),
                ),
                Kind::UInt { .. } => (
                    "u32".to_string(),
                    format!("self.0.uint(Self::{key})"),
                    format!("self.0.set_uint(Self::{key}, v)"),
                ),
                Kind::Int { .. } => (
                    "i32".to_string(),
                    format!("self.0.int(Self::{key})"),
                    format!("self.0.set_int(Self::{key}, v)"),
                ),
                Kind::Double { .. } => (
                    "f64".to_string(),
                    format!("self.0.double(Self::{key})"),
                    format!("self.0.set_double(Self::{key}, v)"),
                ),
                Kind::Choice { .. } => (
                    camel(k.name),
                    format!("{}::parse(&self.0.string(Self::{key}))", camel(k.name)),
                    format!("self.0.set_string(Self::{key}, v.as_str())"),
                ),
                Kind::Str { .. } | Kind::Color { .. } => (
                    "String".to_string(),
                    format!("self.0.string(Self::{key}).to_string()"),
                    format!("self.0.set_string(Self::{key}, &v)"),
                ),
                Kind::StrList { .. } | Kind::Accel { .. } => (
                    "Vec<String>".to_string(),
                    format!("self.0.strv(Self::{key}).iter().map(|s| s.to_string()).collect()"),
                    format!(
                        "self.0.set_strv(Self::{key}, v.iter().map(String::as_str).collect::<Vec<_>>().as_slice())"
                    ),
                ),
            };
            let _ = writeln!(o, "\n    /// {}", k.schema_summary());
            let _ = writeln!(o, "    pub fn {m}(&self) -> {ty} {{\n        {get}\n    }}");
            let _ = writeln!(
                o,
                "\n    pub fn set_{m}(&self, v: {ty}) -> Result<(), gio::glib::BoolError> {{\n        {set}\n    }}"
            );
        }
        o.push_str("}\n\n");
    }
    while o.ends_with("\n\n") {
        o.pop();
    }
    o
}

// ------------------------------------------------------------------ docs/settings.md

fn kind_doc(k: &Kind) -> (String, String) {
    match k {
        Kind::Bool { .. } => ("boolean".into(), String::new()),
        Kind::UInt { min, max, step, .. } => {
            ("unsigned".into(), format!("{min}…{max} (step {step})"))
        }
        Kind::Int { min, max, step, .. } => {
            ("integer".into(), format!("{min}…{max} (step {step})"))
        }
        Kind::Double { min, max, step, .. } => {
            ("number".into(), format!("{min}…{max} (step {step})"))
        }
        Kind::Color { .. } => (
            "colour".into(),
            "CSS colour (`#rgb`, `#rrggbb`, `#rrggbbaa`, `rgb()`, `rgba()`) or empty".into(),
        ),
        Kind::Choice { choices, .. } => (
            "choice".into(),
            choices
                .iter()
                .map(|c| format!("`{}`", c.value))
                .collect::<Vec<_>>()
                .join(", "),
        ),
        Kind::Str { .. } => ("string".into(), String::new()),
        Kind::StrList { .. } => ("string list".into(), String::new()),
        Kind::Accel { .. } => ("shortcut list".into(), String::new()),
    }
}

fn md_cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

fn widget_doc(k: &Key) -> String {
    let page = PAGES.iter().find(|p| p.keys().any(|x| std::ptr::eq(x, k)));
    let row = match (k.widget, &k.kind) {
        _ if SHORTCUTS
            .iter()
            .any(|s| std::ptr::eq(s.key, k) || std::ptr::eq(s.override_key, k)) =>
        {
            return "shortcut row on `--page shortcuts`".into();
        }
        (Widget::Hidden, _) => return "— (gsettings only)".into(),
        (Widget::Display, _) => "read-only row",
        (_, Kind::Bool { .. }) => "switch",
        (_, Kind::UInt { .. } | Kind::Int { .. } | Kind::Double { .. }) => "spin button",
        (_, Kind::Color { .. }) => "entry (colour, checked)",
        (_, Kind::Choice { .. }) => "drop-down",
        (_, Kind::Str { .. }) => "entry",
        (_, Kind::StrList { .. }) => "list",
        (_, Kind::Accel { .. }) => "shortcut",
    };
    match page {
        Some(p) => format!("{row} on `--page {}`", p.id),
        None => row.into(),
    }
}

pub fn origin_text(o: &Origin) -> String {
    match o {
        Origin::Has(s) => s.to_string(),
        Origin::BasedOn { project, licence } => format!("Based on {project} ({licence})"),
    }
}

pub fn settings_md() -> String {
    let mut o = String::new();
    o.push_str(
        "<!-- GENERATED by `cargo xtask gen` from crates/desk-settings/src/registry.rs. Do not edit. -->\n\
         # Settings\n\n\
         Every setting of desktop-themes-rs is declared once, in\n\
         [`crates/desk-settings/src/registry.rs`](../crates/desk-settings/src/registry.rs). From that\n\
         registry `cargo xtask gen` generates the GSettings schema\n\
         (`data/io.github.OlehDzhumyk.Desk.gschema.xml`), the typed Rust accessors\n\
         (`crates/desk-settings/src/accessors.rs`) and this page; the window builds its preference pages\n\
         from it at run time (`themes gui --page <page>`). `cargo test` fails while a generated file is\n\
         out of date.\n\n\
         Labels are English gettext ids; the Ukrainian texts are in `po/uk.po` (see\n\
         [i18n.md](i18n.md)). Change values with the window, or e.g.\n\
         `gsettings set io.github.OlehDzhumyk.Desk.Clipboard history-size 100`.\n\n\
         Colour keys hold a CSS colour or are empty; the window, `themes apply` and the extension that \
         reads them accept only `#rgb`, `#rgba`, `#rrggbb`, `#rrggbbaa`, `rgb()` and `rgba()` (anything \
         else would end up in a style string).\n\n",
    );
    o.push_str("## Features\n\n| Feature | Origin |\n|---|---|\n");
    for f in FEATURES {
        let origins: Vec<String> = f.origins.iter().map(origin_text).collect();
        let _ = writeln!(
            o,
            "| {} (`{}`) | {} |",
            f.title,
            f.id,
            if origins.is_empty() {
                "—".into()
            } else {
                origins.join("; ")
            }
        );
    }
    for s in all_schemas() {
        let _ = writeln!(o, "\n## `{}`\n\nPath `{}`.", s.id, s.path);
        if let Some(e) = EXTENSION_SCHEMAS.iter().find(|e| std::ptr::eq(e.schema, s)) {
            let _ = writeln!(
                o,
                "\nSchema of the extension `{}` (file `{}`, compiled next to the extension).",
                e.uuid,
                e.file()
            );
        }
        o.push('\n');
        o.push_str(
            "| Key | Type | Default | Range / choices | Label | Description | Feature | Window |\n",
        );
        o.push_str("|---|---|---|---|---|---|---|---|\n");
        for k in s.keys {
            let (ty, range) = kind_doc(&k.kind);
            let desc = if k.schema_description().is_empty() {
                k.schema_summary()
            } else {
                k.schema_description()
            };
            let _ = writeln!(
                o,
                "| `{}` | {} | `{}` | {} | {} | {} | {} | {} |",
                k.name,
                ty,
                md_cell(&k.kind.default_text()),
                md_cell(&range),
                md_cell(k.label),
                md_cell(desc),
                k.feature,
                widget_doc(k)
            );
        }
    }
    o.push_str(
        "\n## Shortcuts\n\nThe theme default is written into the key in force (what the bridge binds); the override \
         wins, survives theme switches and is re-applied by every `themes apply`. Empty override = \
         follow the theme; `['disabled']` = no shortcut.\n\n\
         | Id | Label | Feature | Key in force | Override |\n|---|---|---|---|---|\n",
    );
    for s in SHORTCUTS {
        let _ = writeln!(
            o,
            "| `{}` | {} | {} | `{}` | `{}` |",
            s.id,
            md_cell(s.label),
            s.feature,
            md_cell(&crate::dconf_path(s.key)),
            md_cell(&crate::dconf_path(s.override_key)),
        );
    }
    o.push_str("\n## Pages of the window\n\n| Page | Title | Groups |\n|---|---|---|\n");
    for p in PAGES {
        let groups: Vec<&str> = p
            .groups
            .iter()
            .map(|g| {
                if g.title.is_empty() {
                    "(actions)"
                } else {
                    g.title
                }
            })
            .collect();
        let groups = match p.kind {
            PageKind::Credits => "generated from CREDITS.md".to_string(),
            PageKind::Settings => groups.join(", "),
        };
        let _ = writeln!(o, "| `{}` | {} | {} |", p.id, p.title, groups);
    }
    o
}
